package control

import "net/http"

func (s *Server) handleAccountPage(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/account/" {
		http.NotFound(w, r)
		return
	}
	if !accountMethod(w, r, "GET") {
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Content-Security-Policy", "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'")
	w.Write([]byte(accountPage))
}

// Browser callbacks keep a useful recovery path without echoing provider
// errors, principal identifiers, codes, state or membership diagnostics.
func accountLoginFailure(w http.ResponseWriter, status int) {
	accountPrivate(w)
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Content-Security-Policy", "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'")
	w.WriteHeader(status)
	w.Write([]byte(`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mnet - sign-in not completed</title><style>:root{font:100% system-ui,sans-serif;color:#162b33;background:#f4f7f6;color-scheme:light}*{box-sizing:border-box}body{max-width:720px;margin:56px auto;padding:0 24px;line-height:1.65}main{background:white;border:1px solid #d5e1dd;border-radius:20px;padding:28px}h1{font-size:1.875rem;line-height:1.2;letter-spacing:-.03em}h1,p,footer{overflow-wrap:anywhere}a{color:#086963;text-underline-offset:4px}:focus-visible{outline:3px solid #b66022;outline-offset:4px}footer{font-size:.875rem;margin-top:30px;color:#4d6269}@media(max-width:600px){body{margin:24px auto;padding:0 18px}main{padding:22px 18px}h1{font-size:1.25rem}}</style><main><h1>Sign-in was not completed</h1><p>This login may have expired, been refused or opened in a different browser. Your identity must already have access to the selected network.</p><p><a href="/account/">Return to account sign-in</a> and start again in this browser. If access is still refused, ask your network operator to check membership and login setup.</p><p>Retrying does not enroll a device or grant membership. An existing session may still be active; use Sign out from the account page if needed.</p></main><footer>Mnet is provided by Fintex Australia Pty Ltd (ABN 60 688 406 108), New South Wales, Australia. Contact: <a href="mailto:contact@fintex.au">contact@fintex.au</a>.</footer></html>`))
}

const accountPage = `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mnet - your devices</title><style>
:root{font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#162b33;background:#f4f7f6;color-scheme:light;font-size:100%}*{box-sizing:border-box}h1,h2,p,label{overflow-wrap:anywhere}input,select{min-width:0}body{max-width:1040px;margin:0 auto;padding:36px 28px}header{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:24px;margin-bottom:32px}h1{font-size:2.125rem;letter-spacing:-.035em;margin:0 0 8px;line-height:1.2}h2{font-size:1.562rem;letter-spacing:-.025em;line-height:1.25;margin:0 0 16px}p{line-height:1.65;margin:12px 0}a{color:#086963;text-underline-offset:4px}header>a{max-width:100%;padding:12px 16px;border:1px solid #d5e1dd;border-radius:12px;text-decoration:none;font-weight:600;white-space:nowrap}main{margin:0}#message{background:#eaf3ef;border:1px solid #d5e1dd;border-radius:16px;padding:16px 20px;line-height:1.55;margin-bottom:20px;overflow-wrap:anywhere}section{background:white;border:1px solid #d5e1dd;border-radius:20px;padding:28px}#login{max-width:620px}label{display:block;font-size:0.875rem;font-weight:650;margin:20px 0 8px}input{width:100%;border:1px solid #9aafaa;border-radius:12px;padding:14px;font:inherit;color:#162b33;background:#fff;min-height:50px}button{background:#086963;color:white;border:0;border-radius:12px;padding:14px 20px;font:inherit;font-weight:600;cursor:pointer;margin:16px 6px 0 0;min-height:50px}button:hover{background:#07564f}button:disabled{background:#d5e1dd;color:#4d6269;cursor:wait}.secondary{background:#eaf3ef;color:#086963}.secondary:hover{background:#d5e1dd}:focus-visible{outline:3px solid #b66022;outline-offset:4px}.hint,footer{font-size:0.875rem;color:#4d6269;line-height:1.6}.eyebrow{text-transform:uppercase;font-size:0.75rem;letter-spacing:.09em;font-weight:700;color:#086963;margin:0 0 10px}.scope{border-left:3px solid #086963;padding:4px 0 4px 16px;margin:20px 0}.network-context{background:#f4f7f6;border-radius:12px;padding:12px 16px;overflow-wrap:anywhere}.device-table{width:100%;border-collapse:collapse;text-align:left;margin:24px 0 12px}th,td{padding:18px 12px;border-bottom:1px solid #d5e1dd;overflow-wrap:anywhere}th{font-size:0.8125rem;color:#4d6269;font-weight:650}td:first-child{font-weight:600}.address{font-family:ui-monospace,monospace;font-size:0.875rem}#empty{padding:24px;background:#f4f7f6;border:1px dashed #9aafaa;border-radius:12px}footer{margin:32px 0;max-width:760px}[hidden]{display:none!important}@media(max-width:600px){body{padding:24px 18px}header{align-items:flex-start;gap:12px}h1{font-size:1.75rem}header>a{padding:10px}section{padding:22px 18px}h2{font-size:1.438rem}th,td{padding:16px 8px}button{width:100%;margin-right:0}.address{font-size:0.8125rem}#message{padding:14px 16px}}@media(min-width:900px){#loginForm{max-width:460px}}@media(prefers-reduced-motion:no-preference){button,a{transition:background-color .15s ease}}
</style><header><div><p class="eyebrow">Mnet / Member account</p><h1>Your Mnet devices</h1><span class="hint">Approved devices, scoped to your identity</span></div><a href="/">Back to Mnet</a></header>
<main><div id="message" role="status" aria-live="polite">Checking your session...</div>
<section id="login" hidden><p class="eyebrow">Member access</p><h2>Sign in to your network</h2><p>Use the network ID provided by your operator. Your identity must already be a member of that network.</p>
<form id="loginForm"><label for="network">Network ID</label><input id="network" name="network_id" autocomplete="off" maxlength="256" required><button id="signIn" type="submit">Continue to sign in</button></form>
<p class="hint scope">Signing in does not enroll a device or grant membership. Ask your operator if access has not been set up.</p></section>
<section id="devices" hidden><p class="eyebrow">Your account</p><h2>Your approved devices</h2><p class="hint network-context">Network ID: <span id="currentNetwork" style="overflow-wrap:anywhere"></span></p><p>Only devices approved with your verified identity in this network appear here. This list is not a live online-status check.</p>
<table class="device-table"><thead><tr><th scope="col">Device</th><th scope="col">Mesh address</th></tr></thead><tbody id="deviceRows"></tbody></table><p id="empty" hidden>No approved, unexpired devices were found for your identity.</p>
<button class="secondary" id="refresh" type="button">Refresh</button> <button class="secondary" id="logout" type="button">Sign out</button>
<p class="hint">Signing out ends this browser session. It does not disconnect VPN devices.</p></section></main>
<footer>Mnet is provided by Fintex Australia Pty Ltd (ABN 60 688 406 108), New South Wales, Australia. Contact: <a href="mailto:contact@fintex.au">contact@fintex.au</a>.</footer>
<script>
const el=id=>document.getElementById(id);let generation=0,signingOut=false;
function clearPrivate(){el('currentNetwork').textContent='';el('deviceRows').replaceChildren();el('empty').hidden=true;el('devices').hidden=true;el('network').value='';}
function signedOut(message){clearPrivate();el('login').hidden=false;el('message').textContent=message;}
async function load(){if(signingOut)return;const current=++generation;try{const r=await fetch('/account/api/devices',{cache:'no-store'});if(current!==generation||signingOut)return;if(!r.ok){signedOut('Sign in with an existing network membership.');return;}const data=await r.json();if(current!==generation||signingOut)return;if(!data||typeof data.network_id!=='string'||!data.network_id||!Array.isArray(data.devices)||!data.devices.every(device=>device&&typeof device.ID==='string'&&device.ID.length>0&&typeof device.Name==='string'&&typeof device.IPv4==='string'))throw Error();const rows=data.devices.map(device=>{const row=document.createElement('tr');for(const [index,value] of [device.Name,device.IPv4].entries()){const cell=document.createElement('td');cell.textContent=value;if(index===1)cell.className='address';row.append(cell);}return row;});el('deviceRows').replaceChildren(...rows);el('currentNetwork').textContent=data.network_id;el('empty').hidden=data.devices.length!==0;el('login').hidden=true;el('devices').hidden=false;el('message').textContent='Signed in. Device approval is separate from current connectivity.';}catch{if(current===generation&&!signingOut){clearPrivate();el('login').hidden=false;el('message').textContent='Could not read your devices. Try again.';}}}
el('loginForm').addEventListener('submit',async e=>{e.preventDefault();el('signIn').disabled=true;el('message').textContent='Opening your identity provider...';try{const r=await fetch('/account/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({network_id:el('network').value.trim()})});if(!r.ok)throw Error();const data=await r.json();const target=new URL(data.authorization_url);if(!['https:','http:'].includes(target.protocol))throw Error();location.assign(target.href);}catch{el('message').textContent='Could not start sign-in. Check the network ID and ask your operator to confirm login setup.';el('signIn').disabled=false;}});
el('refresh').addEventListener('click',load);
el('logout').addEventListener('click',async()=>{if(signingOut)return;signingOut=true;++generation;clearPrivate();el('login').hidden=true;el('message').textContent='Signing out...';try{const r=await fetch('/account/api/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error();signedOut('Signed out.');}catch{el('login').hidden=true;el('message').textContent='Could not confirm sign-out. Retry before leaving this browser.';el('devices').hidden=false;}finally{signingOut=false;}});
load();
</script></html>`
